def exact_small(n, a, b):
    sa = 0
    sb = 0
    for i, c in enumerate(a):
        if c == '1':
            sa |= 1 << i
    for i, c in enumerate(b):
        if c == '1':
            sb |= 1 << i

    dist = [-1] * (1 << n)
    dist[sa] = 0
    q = deque([sa])

    while q:
        mask = q.popleft()
        if mask == sb:
            return dist[mask]
        nd = dist[mask] + 1
        for p in range(n):
            left = mask & ((1 << p) - 1)
            right = mask >> (p + 1)
            center = (mask >> p) & 1

            nxt = (left << 1) | (right << p)
            if center:
                nxt |= 1 << p
            if p > 0 and ((mask >> (p - 1)) & 1):
                nxt |= 1 << p
            if p + 1 < n and ((mask >> (p + 1)) & 1):
                nxt |= 1 << p

            if dist[nxt] == -1:
                dist[nxt] = nd
                q.append(nxt)

    return -1


def solve_equal_count(a_pos, b_pos):
    d = [y - x for x, y in zip(a_pos, b_pos)]

    for i in range(len(d) - 1):
        if d[i] < d[i + 1]:
            return -1

    low = max(abs(x) for x in d)
    m = len(d)

    # For a fixed number D of operations, particle i needs a waiting step
    # exactly when D and its displacement have different parity. At most one
    # unmerged particle can wait in each operation.
    for ans in range(low, low + 2 * m + 5):
        need = 0
        parity = ans & 1
        for x in d:
            if (x & 1) != parity:
                need += 1
        if need <= ans:
            return ans

    return -1


def heuristic_general(n, a, b):
    a_pos = [i for i, c in enumerate(a) if c == '1']
    b_pos = [i for i, c in enumerate(b) if c == '1']

    if len(a_pos) < len(b_pos):
        return -1

    if len(a_pos) == len(b_pos):
        return solve_equal_count(a_pos, b_pos)

    # Select one representative source piece for every target occupied square.
    # The remaining pieces can merge into one of the selected trajectories.
    k = len(b_pos)
    m = len(a_pos)

    chosen = []
    prev = -1
    ptr = 0

    for i, y in enumerate(b_pos):
        remaining_targets = k - i - 1
        limit = m - remaining_targets - 1

        best = -1
        while ptr <= limit:
            x = a_pos[ptr]
            if best == -1:
                best = ptr
            if prev != -1:
                old_d = b_pos[i - 1] - a_pos[prev]
                new_d = y - x
                if new_d <= old_d:
                    best = ptr
            ptr += 1

        if best == -1:
            return -1

        chosen.append(best)
        prev = best
        ptr = best + 1

    rep_a = [a_pos[i] for i in chosen]
    ans = solve_equal_count(rep_a, b_pos)
    if ans < 0:
        return -1

    # Every non-representative piece must be able to reach some target square.
    for x in a_pos:
        lo = 0
        hi = k
        while lo < hi:
            mid = (lo + hi) // 2
            if b_pos[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        dist = n + 1
        if lo < k:
            dist = min(dist, abs(x - b_pos[lo]))
        if lo:
            dist = min(dist, abs(x - b_pos[lo - 1]))
        ans = max(ans, dist)

    return ans


def main():
    it = iter(sys.stdin.read().split())
    t = int(next(it))
    out = []

    for _ in range(t):
        n = int(next(it))
        a = next(it)
        b = next(it)

        # The exhaustive solver is retained for tiny instances, where it gives
        # the exact answer directly and covers all delicate merging cases.
        if n <= 18:
            out.append(str(exact_small(n, a, b)))
        else:
            out.append(str(heuristic_general(n, a, b)))

    print("\n".join(out))


if __name__ == "__main__":
    main()

from typing import List


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Canonical clockwise perimeter coordinate:
        # bottom: [0, side), right: [side, 2*side),
        # top: [2*side, 3*side), left: [3*side, 4*side).
        pos = []
        for x, y in points:
            if y == 0:
                pos.append(x)
            elif x == side:
                pos.append(side + y)
            elif y == side:
                pos.append(3 * side - x)
            else:
                pos.append(4 * side - y)

        pos.sort()
        n = len(pos)
        perimeter = 4 * side

        # For k >= 4, a distance greater than side is impossible:
        # four selected points would need one point on each canonical side.
        # The four adjacent-side distances sum exactly 4*side, so they
        # cannot all be greater than side.
        #
        # Hence only d <= side needs checking. In this range, every
        # opposite-side pair is automatically at distance >= side >= d,
        # and all other relevant constraints are exactly circular
        # perimeter spacing constraints.
        doubled = pos + [x + perimeter for x in pos]

        def feasible(d: int) -> bool:
            nxt = [2 * n] * (2 * n + 1)
            j = 0

            # nxt[i] is the first perimeter point at least d ahead of i.
            for i in range(2 * n):
                if j < i + 1:
                    j = i + 1
                target = doubled[i] + d
                while j < 2 * n and doubled[j] < target:
                    j += 1
                nxt[i] = j

            # Try every point as the first selected point. Greedily taking
            # earliest possible successors is optimal for a fixed first point.
            for start in range(n):
                cur = start
                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= 2 * n:
                        break

                # Last-to-first wraparound perimeter gap must also be >= d.
                if cur < start + n and doubled[cur] <= doubled[start] + perimeter - d:
                    return True

            return False

        lo, hi = 0, side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

import sys

def solve():
    input = sys.stdin.buffer.readline
    n = int(input())
    adj = [[] for _ in range(n)]
    for _ in range(n - 1):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        adj[a].append(b)
        adj[b].append(a)

    eligible = [len(adj[v]) >= 4 for v in range(n)]
    if not any(eligible):
        print(-1)
        return

    parent = [-1] * n
    order = [0]
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # down[u] = directed message u -> parent[u]:
    # best skeleton size in u's side when u is connected to its parent.
    down = [0] * n

    for u in reversed(order):
        if not eligible[u]:
            continue

        best = []
        for v in adj[u]:
            if parent[v] == u and eligible[v]:
                x = down[v]
                best.append(x)
                i = len(best) - 1
                while i > 0 and best[i] > best[i - 1]:
                    best[i], best[i - 1] = best[i - 1], best[i]
                    i -= 1
                if len(best) > 3:
                    best.pop()

        down[u] = 1 + sum(best)

    # up[u] = directed message parent[u] -> u, if that endpoint is eligible.
    up = [0] * n
    best_internal_count = 1

    for u in order:
        if not eligible[u]:
            continue

        # At most four incoming branches may be selected at a top vertex.
        best4 = []

        p = parent[u]
        if p != -1 and eligible[p]:
            best4.append((up[u], p))

        for v in adj[u]:
            if parent[v] == u and eligible[v]:
                item = (down[v], v)
                best4.append(item)
                i = len(best4) - 1
                while i > 0 and best4[i][0] > best4[i - 1][0]:
                    best4[i], best4[i - 1] = best4[i - 1], best4[i]
                    i -= 1
                if len(best4) > 4:
                    best4.pop()

        best_internal_count = max(
            best_internal_count,
            1 + sum(value for value, _ in best4)
        )

        # Send messages u -> eligible child.
        for v in adj[u]:
            if parent[v] != u or not eligible[v]:
                continue

            total = 0
            taken = 0
            for value, neighbor in best4:
                if neighbor != v:
                    total += value
                    taken += 1
                    if taken == 3:
                        break
            up[v] = 1 + total

    print(3 * best_internal_count + 2)

if __name__ == "__main__":
    solve()

