class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        total = n * m

        # Clockwise direction cycle in row/column coordinates.
        # NW -> NE -> SE -> SW -> NW
        directions = [(-1, -1), (-1, 1), (1, 1), (1, -1)]

        # suffix[d] = (lengths starting with required 0, lengths starting with required 2)
        # Each length follows direction d and alternates 0, 2, 0, 2, ...
        suffix = []

        for dr, dc in directions:
            # Process every cell after its next cell in direction (dr, dc).
            r_start, r_end, r_step = (n - 1, -1, -1) if dr == 1 else (0, n, 1)
            c_start, c_end, c_step = (m - 1, -1, -1) if dc == 1 else (0, m, 1)

            start_zero = array("H", [0]) * total
            start_two = array("H", [0]) * total

            for r in range(r_start, r_end, r_step):
                nr = r + dr
                base = r * m

                for c in range(c_start, c_end, c_step):
                    idx = base + c
                    value = grid[r][c]
                    nc = c + dc

                    if value == 0:
                        if 0 <= nr < n and 0 <= nc < m:
                            start_zero[idx] = 1 + start_two[nr * m + nc]
                        else:
                            start_zero[idx] = 1
                    elif value == 2:
                        if 0 <= nr < n and 0 <= nc < m:
                            start_two[idx] = 1 + start_zero[nr * m + nc]
                        else:
                            start_two[idx] = 1

            suffix.append((start_zero, start_two))

        answer = 0
        incoming = array("H", [0]) * total

        # For each initial direction, compute the longest valid segment ending
        # at each cell before any clockwise turn.
        for d, (dr, dc) in enumerate(directions):
            # Process after the predecessor (r-dr, c-dc).
            r_start, r_end, r_step = (0, n, 1) if dr == 1 else (n - 1, -1, -1)
            c_start, c_end, c_step = (0, m, 1) if dc == 1 else (m - 1, -1, -1)

            turn_d = (d + 1) % 4
            tr, tc = directions[turn_d]
            turn_zero, turn_two = suffix[turn_d]

            for r in range(r_start, r_end, r_step):
                base = r * m
                pr = r - dr

                for c in range(c_start, c_end, c_step):
                    idx = base + c
                    value = grid[r][c]
                    length = 0
                    pc = c - dc

                    if value == 1:
                        length = 1
                    elif 0 <= pr < n and 0 <= pc < m:
                        previous = incoming[pr * m + pc]
                        if previous:
                            if (previous & 1 and value == 2) or (
                                not (previous & 1) and value == 0
                            ):
                                length = previous + 1

                    incoming[idx] = length

                    if not length:
                        continue

                    if length > answer:
                        answer = length

                    # Turn at this pivot, excluding the pivot from the suffix.
                    nr = r + tr
                    nc = c + tc
                    if 0 <= nr < n and 0 <= nc < m:
                        if length & 1:
                            extra = turn_two[nr * m + nc]
                        else:
                            extra = turn_zero[nr * m + nc]

                        candidate = length + extra
                        if candidate > answer:
                            answer = candidate

        return answer

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(pattern: str):
            m = len(pattern)
            if m == 0:
                return list(range(n + 1))

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        def successor_array(starts):
            present = [False] * (n + 1)
            for pos in starts:
                present[pos] = True

            nxt = [n + 1] * (n + 2)
            nearest = n + 1
            for i in range(n, -1, -1):
                if present[i]:
                    nearest = i
                nxt[i] = nearest
            return nxt

        occ_a = occurrences(a)
        occ_b = occurrences(b)
        occ_c = occurrences(c)

        next_b = successor_array(occ_b)
        next_c = successor_array(occ_c)

        len_a = len(a)
        len_b = len(b)
        len_c = len(c)

        answer = n + 1

        for start_a in occ_a:
            required_b = start_a + len_a
            if required_b > n:
                continue

            start_b = next_b[required_b]
            if start_b > n:
                continue

            required_c = start_b + len_b
            if required_c > n:
                continue

            start_c = next_c[required_c]
            if start_c > n:
                continue

            end_c = start_c + len_c
            if end_c <= n:
                answer = min(answer, end_c - start_a)

        return answer if answer <= n else -1

