def solve():
    N, MOD = map(int, sys.stdin.readline().split())
    H = N // 2
    EMAX = N * (N - 1) // 2

    # Binomial coefficients modulo MOD, for values at most N or EMAX.
    comb_n = [[0] * (N + 1) for _ in range(N + 1)]
    comb_n[0][0] = 1
    for i in range(1, N + 1):
        comb_n[i][0] = comb_n[i][i] = 1
        for j in range(1, i):
            comb_n[i][j] = (comb_n[i - 1][j - 1] + comb_n[i - 1][j]) % MOD

    # Binomial coefficients for converting the (1+x)^q basis to x^m.
    comb_e = [[0] * (EMAX + 1) for _ in range(EMAX + 1)]
    comb_e[0][0] = 1
    for i in range(1, EMAX + 1):
        comb_e[i][0] = comb_e[i][i] = 1
        prev = comb_e[i - 1]
        row = comb_e[i]
        for j in range(1, i):
            row[j] = (prev[j - 1] + prev[j]) % MOD

    # terms[a][b] represents
    # ((1+x)^a - 1)^b * (1+x)^(b*(b-1)/2)
    # as a linear combination of powers of t = 1+x:
    # sum (shift, coefficient) * t^shift.
    terms = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            base = b * (b - 1) // 2
            cur = []
            for j in range(b + 1):
                c = comb_n[b][j]
                if (b - j) & 1:
                    c = (-c) % MOD
                cur.append((base + a * j, c))
            terms[a][b] = cur

    # levels[u][(parity_of_last_layer, even_vertices_so_far, last_layer_size)]
    # is a polynomial in t=1+x, represented by coefficient list.
    levels = [None] * (N + 1)
    levels[1] = {(0, 1, 1): [1]}  # L_0 = {1}

    for used in range(1, N):
        cur_level = levels[used]
        if not cur_level:
            continue

        remaining = N - used

        for (parity, even_count, last_size), src in cur_level.items():
            src_len = len(src)
            next_parity = parity ^ 1

            for b in range(1, remaining + 1):
                next_used = used + b
                next_even = even_count + (b if next_parity == 0 else 0)
                next_odd = next_used - next_even

                if next_even > H or next_odd > H:
                    continue

                # Select which currently unused labels become the next layer.
                label_factor = comb_n[remaining][b]
                key = (next_parity, next_even, b)

                if levels[next_used] is None:
                    levels[next_used] = {}
                target_level = levels[next_used]

                max_shift = last_size * b + b * (b - 1) // 2
                needed_len = src_len + max_shift

                dst = target_level.get(key)
                if dst is None:
                    dst = [0] * needed_len
                    target_level[key] = dst
                elif len(dst) < needed_len:
                    dst.extend([0] * (needed_len - len(dst)))

                # Multiply src by the sparse t-basis representation of the
                # transition polynomial.
                for shift, coef0 in terms[last_size][b]:
                    coef = (coef0 * label_factor) % MOD
                    if coef == 0:
                        continue
                    end = src_len
                    for i in range(end):
                        v = src[i]
                        if v:
                            dst[i + shift] = (dst[i + shift] + v * coef) % MOD

        levels[used] = None

    total_t = [0] * (EMAX + 1)
    final_level = levels[N]
    if final_level:
        for (parity, even_count, last_size), poly in final_level.items():
            if even_count != H:
                continue
            for q, v in enumerate(poly):
                if v:
                    total_t[q] = (total_t[q] + v) % MOD

    # If F(x) = sum_q total_t[q] * (1+x)^q,
    # then [x^m] F = sum_{q>=m} total_t[q] * C(q,m).
    ans = [0] * (EMAX + 1)
    for q, v in enumerate(total_t):
        if v == 0:
            continue
        row = comb_e[q]
        for m in range(q + 1):
            ans[m] = (ans[m] + v * row[m]) % MOD

    print(" ".join(map(str, ans[N - 1:])))

if __name__ == "__main__":
    solve()

import sys

MOD = 998244353


def solve_small_width(H, W, A, updates):
    # Use columns when H is the small dimension; otherwise transpose conceptually
    if H <= W:
        K = H
        L = W

        def make_matrix(line):
            m = [[0] * K for _ in range(K)]
            prod = 1
            for j in range(K):
                prod = 1
                for i in range(j, K):
                    prod = prod * A[i * W + line] % MOD
                    m[i][j] = prod
            return m

        def line_of(r, c):
            return c
    else:
        K = W
        L = H

        def make_matrix(line):
            m = [[0] * K for _ in range(K)]
            for j in range(K):
                prod = 1
                for i in range(j, K):
                    prod = prod * A[line * W + i] % MOD
                    m[i][j] = prod
            return m

        def line_of(r, c):
            return r

    def multiply(a, b):
        # Returns a*b. Every matrix is lower triangular.
        res = [[0] * K for _ in range(K)]
        for i in range(K):
            ri = res[i]
            ai = a[i]
            for t in range(i + 1):
                x = ai[t]
                if x:
                    bt = b[t]
                    for j in range(t + 1):
                        ri[j] = (ri[j] + x * bt[j]) % MOD
        return res

    size = 1
    while size < L:
        size <<= 1

    ident = [[0] * K for _ in range(K)]
    for i in range(K):
        ident[i][i] = 1

    seg = [None] * (2 * size)
    for i in range(size):
        seg[size + i] = make_matrix(i) if i < L else ident

    for i in range(size - 1, 0, -1):
        # Applying left segment then right segment: right * left
        seg[i] = multiply(seg[i << 1 | 1], seg[i << 1])

    out = []
    for r, c, value in updates:
        A[r * W + c] = value
        p = size + line_of(r, c)
        seg[p] = make_matrix(line_of(r, c))
        p >>= 1
        while p:
            seg[p] = multiply(seg[p << 1 | 1], seg[p << 1])
            p >>= 1
        out.append(str(seg[1][K - 1][0]))

    sys.stdout.write("\n".join(out))


def solve_fallback(H, W, A, updates):
    n = H * W

    def build_forward():
        dp = [0] * n
        for i in range(H):
            base = i * W
            left = 0
            if i == 0:
                for j in range(W):
                    p = base + j
                    if j == 0:
                        left = A[p]
                    else:
                        left = left * A[p] % MOD
                    dp[p] = left
            else:
                above = base - W
                for j in range(W):
                    p = base + j
                    left = A[p] * (left + dp[above + j]) % MOD
                    dp[p] = left
        return dp

    def build_backward():
        dp = [0] * n
        for i in range(H - 1, -1, -1):
            base = i * W
            right = 0
            if i == H - 1:
                for j in range(W - 1, -1, -1):
                    p = base + j
                    if j == W - 1:
                        right = A[p]
                    else:
                        right = right * A[p] % MOD
                    dp[p] = right
            else:
                below = base + W
                for j in range(W - 1, -1, -1):
                    p = base + j
                    right = A[p] * (right + dp[below + j]) % MOD
                    dp[p] = right
        return dp

    q = len(updates)
    batches = []
    i = 0
    while i < q:
        r0 = r1 = updates[i][0]
        c0 = c1 = updates[i][1]
        j = i + 1

        while j < q:
            rr, cc, _ = updates[j]
            nr0 = min(r0, rr)
            nr1 = max(r1, rr)
            nc0 = min(c0, cc)
            nc1 = max(c1, cc)
            length = j - i + 1
            area = (nr1 - nr0 + 1) * (nc1 - nc0 + 1)

            if length * area > n and j > i + 1:
                break

            r0, r1, c0, c1 = nr0, nr1, nc0, nc1
            j += 1

        batches.append((i, j, r0, r1, c0, c1))
        i = j

    ans = []

    for lo, hi, r0, r1, c0, c1 in batches:
        forward = build_forward()
        backward = build_backward()
        initial_total = forward[-1]

        bh = r1 - r0 + 1
        bw = c1 - c0 + 1

        def rectangle_contribution():
            prev = [0] * bw
            right_exit = [0] * bh

            for ii in range(bh):
                rr = r0 + ii
                row_base = rr * W
                cur = [0] * bw
                left = 0

                for jj in range(bw):
                    cc = c0 + jj
                    pos = row_base + cc
                    incoming = 0

                    if rr == 0 and cc == 0:
                        incoming = 1
                    else:
                        if ii:
                            incoming += prev[jj]
                        elif rr:
                            incoming += forward[pos - W]

                        if jj:
                            incoming += left
                        elif cc:
                            incoming += forward[pos - 1]

                    left = A[pos] * (incoming % MOD) % MOD
                    cur[jj] = left

                right_exit[ii] = cur[-1]
                prev = cur

            if r0 <= H - 1 <= r1 and c0 <= W - 1 <= c1:
                return prev[W - 1 - c0]

            total = 0

            if r1 + 1 < H:
                below = (r1 + 1) * W
                for j in range(bw):
                    total += prev[j] * backward[below + c0 + j]

            if c1 + 1 < W:
                for i in range(bh):
                    total += right_exit[i] * backward[(r0 + i) * W + c1 + 1]

            return total % MOD

        fixed = (initial_total - rectangle_contribution()) % MOD

        for k in range(lo, hi):
            rr, cc, value = updates[k]
            A[rr * W + cc] = value
            ans.append(str((fixed + rectangle_contribution()) % MOD))

    sys.stdout.write("\n".join(ans))


def solve():
    input = sys.stdin.buffer.readline

    H, W = map(int, input().split())
    A = []
    for _ in range(H):
        A.extend(map(int, input().split()))

    Q, sh, sw = map(int, input().split())
    r = sh - 1
    c = sw - 1

    updates = []
    for _ in range(Q):
        d, x = input().split()
        if d == b"L":
            c -= 1
        elif d == b"R":
            c += 1
        elif d == b"U":
            r -= 1
        else:
            r += 1
        updates.append((r, c, int(x)))

    if min(H, W) <= 6:
        solve_small_width(H, W, A, updates)
    else:
        solve_fallback(H, W, A, updates)


if __name__ == "__main__":
    solve()

import sys


def mat_mul(a, b, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        ri = res[i]
        ai = a[i]
        for k, x in enumerate(ai):
            if x:
                bk = b[k]
                for j in range(n):
                    ri[j] += x * bk[j]
        for j in range(n):
            ri[j] %= mod
    return res


def mat_pow(a, e, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1

    while e:
        if e & 1:
            res = mat_mul(res, a, mod)
        a = mat_mul(a, a, mod)
        e >>= 1
    return res


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, p = data[0], data[1]
    a = []
    pos = 2
    for _ in range(n):
        a.append(data[pos:pos + n])
        pos += n

    # For p = 2, every entry becomes 1, since the only nonzero field element is 1.
    if p == 2:
        x = n & 1
        line = " ".join([str(x)] * n)
        sys.stdout.write("\n".join([line] * n))
        return

    zero_count = 0
    c = [[0] * n for _ in range(n)]
    diag_zero = [False] * n

    for i in range(n):
        for j in range(n):
            if a[i][j] == 0:
                zero_count += 1
                if i == j:
                    diag_zero[i] = True
            else:
                c[i][j] = a[i][j] % p

    ans = mat_pow(c, p, p)

    # For p > 3, the only exceptional surviving walks use a zero diagonal
    # edge p-1 times, with one fixed nonzero edge at the beginning or end.
    # These contribute C*D + D*C, where D marks zero diagonal positions.
    for i in range(n):
        for j in range(n):
            add = 0
            if diag_zero[j]:
                add += c[i][j]
            if diag_zero[i]:
                add += c[i][j]
            ans[i][j] = (ans[i][j] + add) % p

    # For p = 3 only, a non-loop zero edge u->v may occur as
    # (u->v), (v->u), (u->v). Its contribution is C[v][u].
    if p == 3:
        for i in range(n):
            for j in range(n):
                if i != j and a[i][j] == 0:
                    ans[i][j] = (ans[i][j] + c[j][i]) % p

    if zero_count & 1:
        for i in range(n):
            for j in range(n):
                ans[i][j] = (-ans[i][j]) % p

    sys.stdout.write("\n".join(" ".join(map(str, row)) for row in ans))


if __name__ == "__main__":
    main()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(limit: int) -> bool:
            if limit == 1:
                mismatch_start_zero = 0
                mismatch_start_one = 0

                for i, ch in enumerate(s):
                    if ch != ('0' if i % 2 == 0 else '1'):
                        mismatch_start_zero += 1
                    if ch != ('1' if i % 2 == 0 else '0'):
                        mismatch_start_one += 1

                return min(mismatch_start_zero, mismatch_start_one) <= numOps

            flips_needed = 0
            run_length = 1

            for i in range(1, n + 1):
                if i < n and s[i] == s[i - 1]:
                    run_length += 1
                else:
                    flips_needed += run_length // (limit + 1)
                    if flips_needed > numOps:
                        return False
                    run_length = 1

            return True

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2
            if feasible(mid):
                right = mid
            else:
                left = mid + 1

        return left

import sys


def solve():
    input = sys.stdin.buffer.readline
    n = int(input())
    a = list(map(int, input().split()))

    size = 1
    while size < n:
        size <<= 1
    seg = [0] * (2 * size)
    seg[size:size + n] = a
    for i in range(size - 1, 0, -1):
        left = seg[i << 1]
        right = seg[i << 1 | 1]
        seg[i] = left if left >= right else right

    def range_max(l, r):
        # Inclusive endpoints.
        l += size
        r += size
        res = 0
        while l <= r:
            if l & 1:
                if seg[l] > res:
                    res = seg[l]
                l += 1
            if not (r & 1):
                if seg[r] > res:
                    res = seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        return res

    def find_first(l, r, value):
        # Find the leftmost index in [l,r] having exactly value.
        stack = [(1, 0, size - 1)]
        while stack:
            node, nl, nr = stack.pop()
            if nr < l or r < nl or seg[node] < value:
                continue
            if nl == nr:
                return nl
            mid = (nl + nr) >> 1
            # Push right first, so left is processed first.
            stack.append((node << 1 | 1, mid + 1, nr))
            stack.append((node << 1, nl, mid))
        return -1

    pref = [0] * (n + 1)
    for i, x in enumerate(a):
        pref[i + 1] = pref[i] + x

    # Each segment record: [l, r, maximum, positions_of_maximum, child_ids]
    segments = []
    segments.append([0, n - 1, 0, None, None])

    ptr = 0
    while ptr < len(segments):
        l, r, _, _, _ = segments[ptr]
        maximum = range_max(l, r)

        maxima = []
        children_ranges = []
        pending = [(l, r)]

        while pending:
            x, y = pending.pop()
            if x > y:
                continue
            cur = range_max(x, y)
            if cur == maximum:
                p = find_first(x, y, maximum)
                maxima.append(p)
                if x < p:
                    pending.append((x, p - 1))
                if p < y:
                    pending.append((p + 1, y))
            else:
                children_ranges.append((x, y))

        maxima.sort()
        child_ids = []
        for x, y in children_ranges:
            child_ids.append(len(segments))
            segments.append([x, y, 0, None, None])

        segments[ptr] = [l, r, maximum, maxima, child_ids]
        ptr += 1

    m = len(segments)
    head = [-1] * m
    tail = [-1] * m
    ans = [0] * n
    nxt = [-1] * n

    def finalize(group_id, value):
        p = head[group_id]
        while p != -1:
            ans[p] = value
            p = nxt[p]

    for sid in range(m - 1, -1, -1):
        l, r, maximum, maxima, child_ids = segments[sid]
        total = pref[r + 1] - pref[l]

        h = -1
        t = -1

        def append_group(gid):
            nonlocal h, t
            if head[gid] == -1:
                return
            if h == -1:
                h = head[gid]
                t = tail[gid]
            else:
                nxt[t] = head[gid]
                t = tail[gid]

        for cid in child_ids:
            cl, cr = segments[cid][0], segments[cid][1]
            child_sum = pref[cr + 1] - pref[cl]
            if head[cid] != -1:
                if child_sum > maximum:
                    append_group(cid)
                else:
                    finalize(cid, child_sum)

        for p in maxima:
            can_start = (
                (p > l and a[p - 1] < maximum) or
                (p < r and a[p + 1] < maximum)
            )
            if can_start:
                if h == -1:
                    h = t = p
                else:
                    nxt[t] = p
                    t = p
            else:
                ans[p] = maximum

        head[sid] = h
        tail[sid] = t

    root_sum = pref[n]
    if head[0] != -1:
        finalize(0, root_sum)

    print(*ans)


if __name__ == "__main__":
    solve()

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(threshold + 1))
        size = [1] * (threshold + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        valid = []
        isolated = 0

        for x in nums:
            if x <= threshold:
                valid.append(x)
            else:
                isolated += 1

        representative = [0] * (threshold + 1)

        for value in valid:
            for multiple in range(value, threshold + 1, value):
                if representative[multiple] == 0:
                    representative[multiple] = value
                else:
                    union(value, representative[multiple])

        components = sum(1 for value in valid if find(value) == value)
        return components + isolated
